let colors = ['#e6302b', '#fbd400', '#36ad63', '#2B50AA', '#e3e3e3', '#f654a9'];
let ctx;
let centerX, centerY;

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;

	shuffle(colors, true);

	let cellCount = 90;
	let gridArea = width * 1.1;
	let cellSize = gridArea / cellCount;
	let w = cellSize;
	background('#232323');
	for (let j = 0; j < cellCount; j++) {
		for (let i = 0; i < cellCount; i++) {
			let x = i * cellSize + (cellSize / 2) + (width - gridArea) / 2;
			let y = j * cellSize + (cellSize / 2) + (height - gridArea) / 2;
			let clr1 = '🐮';
			let clr2 = '🐮';
			let nns = floor(map(noise(x * 0.006, y * 0.006), 0, 1, 0, 30));
			let shapeType = nns % 5;
			let ang = int(random(4)) * (TAU / 4);
			while (clr1 == clr2) {
				clr1 = colors[nns % colors.length];
				clr2 = colors[(nns + 1) % colors.length];
			}
			push();
			translate(x, y);
			noStroke();
			rotate(ang);
			fill(clr1);
			if (shapeType == 0) {
				if ((i + j) % 2 == 0) {
					square(0, 0, w);
				}
			} else if (shapeType == 1) {
				square(0, 0, w);
				fill(random(colors));
				circle(0, 0, w * 0.5);
			} else if (shapeType == 2) {
				triangle(w / 2, -w / 2, w / 2, w / 2, -w / 2, w / 2,);
			} else if (shapeType == 3) {
				stroke(clr1);
				strokeWeight(w * 0.2);
				line(w / 2, w / 2, -w / 2, -w / 2);
			} else if (shapeType == 4) {
				noFill();
				stroke(clr1);
				strokeWeight(w * 0.2);
				arc(-w / 2, -w / 2, w, w, 0, PI / 2);
				arc(w / 2, w / 2, w, w, PI, PI * 1.5);
			}
			pop();
		}
	}
}

